use super::*;
use crate::views::offline::{self,CacheScope};
impl Backend{
 fn projection_scope(&self)->Result<CacheScope>{let client=self.client()?;Ok(CacheScope{profile_id:self.current_profile_id()?,network_id:client.network_id().into(),client_id:client.client_id().into(),target_node:client.target_node().into()})}
 fn projection_path(&self)->Result<PathBuf>{let target=self.client()?.target_node();ensure!(target.len()==64&&target.bytes().all(|byte|byte.is_ascii_digit()||(b'a'..=b'f').contains(&byte)),"离线视图Node标识无效");Ok(self.client_directory()?.join("workspace-cache").join(format!("{target}.json")))}
 pub(super) async fn save_projection(&self)->Result<()>{if !self.state.online||!self.state.synced||!self.client()?.can_write(){return Ok(())}let scope=self.projection_scope()?;let snapshot=self.state.clone();let conversation=self.conversation.clone();let path=self.projection_path()?;tokio::task::spawn_blocking(move||{let bytes=offline::encode(&snapshot,&scope,conversation.as_deref())?;vibeface_bridge::platform::privatefs::create_dir(path.parent().context("离线视图缺少父目录")?)?;vibeface_bridge::platform::privatefs::write_atomic(&path,&bytes)}).await?}
 pub(super) async fn load_projection(&mut self)->Result<()>{let client=self.client()?.clone();let scope=self.projection_scope()?;let path=self.projection_path()?;let cached=tokio::task::spawn_blocking(move||->Result<_>{if !path.try_exists()?{return Ok(None)}let bytes=vibeface_bridge::platform::privatefs::read_private_bounded(&path,offline::MAX_CACHE_BYTES as u64,"离线工作区视图")?;Ok(Some(offline::decode(&bytes,&scope)?))}).await??;
  if let Some(cached)=cached{self.conversation=cached.conversation_id().map(str::to_owned);self.state=cached.into_snapshot(self.state.generation,client.can_save_locally());}else{self.state.online=false;self.state.synced=false;self.state.writable=false;self.state.can_save_locally=false;self.state.status="身份已在本机解锁，但此Node没有可验证工作区缓存。已有待发记录保留；连接后再读取输入目标。".into();}
  self.state.drafts=load_draft_summaries(self.draft_dir()?).await?;self.state.pending=client.pending().await?.into_iter().map(|operation|Pending{id:operation.id,state:operation_label(operation.state).into()}).collect();self.state.can_configure_owner=self.host.snapshot().selected.is_some();self.publish();Ok(())
 }
}
